# -*- coding: utf-8 -*-
import sys; sys.path.insert(0, "Tools/prd_ledger/70")
from _lib import c, table, save

c(1, "header lines 1-5; §2.1 table (verbatim); §2.2 table (verbatim)", "positioning", "Habit: Daily routine tracker / 継続する技術 (App Store ID 1120239484; 'Goal planner & Streaks') by bondavi Inc. (info.todice.habit) — a single-habit tracker: one goal guided down to five minutes or less, days and a reminder time, one tap on a ring that fills over a 30-day cycle, a stick-figure character's encouragement line after each tap, a two-day-miss reset prompt, previous day recordable until 3 a.m., a History of cycles, columns and developer essays; an optional add-on 「無駄機能」 ('useless feature') unlocks alternative message packs including a 中二病 voice; 2,290 reviews (every one read and hand-coded), 11 storefronts, 4 languages (Japanese 2,264, Chinese 18, English 7, Russian 1), 2016-06-20 → 2026-09-06, mean 4.73; listing (lookup API 2026-09-14): Health & Fitness, 4+, released 2016-06-18, version 1.34.3 dated 2026-09-10, free, 33 declared language codes; JP: 「完全無料。（アプリ内課金は、応援したい人だけのものです。なくても全く困りません）」 and 「広告なし。（そのため、清々しいほど儲かりません）」 (no ads, 'that is why we make refreshingly little money'); claims 12,000 people a month complete 30 days and input takes 'three seconds a day'; US: 'the app only allows you to set one goal at a time'; the current JP release note is a serialised essay about writing a novel; capabilities (verbatim): " + table("## 2.1 What the product is", 0) + " || listings (verbatim): " + table("## 2.2 What the store listing says", 0), "free, no ads; optional patronage add-on", "praise", "2,290 reviews; mean 4.73; JP public 4.78 on 53,106", "none", "header", "app-specific", ["5953466116"])
c(2, "How to read this; Warnings 1, 2, 3, 5, 8; §1.1 table (verbatim); §1.2 table (verbatim); §1.3; §1.4; §1.5 table (verbatim); §1.6", "data-caveat", "Method and limits: non-exclusive counts; IDs plus date-order index; read in 23 batches of up to 100 in original language; per-batch re-assertion of IDs and, from batch 10, of every quoted fragment — this caught drifted IDs in early batches; unknown codes rejected, 9 unions; build refuses non-verbatim quotations and asserts trend directions; files (verbatim) " + table("## 1.1 Files used", 0) + "; schema (verbatim) " + table("## 1.2 Schema actually present", 0) + "; reconciliation: 2,290 distinct IDs, no duplicates, 11 country files match, manifest {1: 50, 2: 26, 3: 64, 4: 202, 5: 1948}, mean 4.7345, 38 storefronts probed all complete, 11 edited, 227 with votes (max 354), 8 short generic bodies recur across authors years apart and are kept; bands (verbatim) " + table("## 1.5 Signal thresholds", 0) + "; a Japanese corpus (jp 2,259 = 98.65%; no other storefront reaches 50); overwhelmingly positive (5★ 85.07%, 1–2★ 3.32%) so a 1% theme is ~23 reviews; the corpus agrees with the public rating (4.73 vs 4.78 on 53,106; written ≈ 4.3% of JP ratings); outcomes self-reported (one claims 10 kg in a week); codes hand judgement; limitations: selection toward people who succeeded, one market, no version data, prices from reviewers, thin late period (E5 211)", "n/a", "praise", "2,290 read; 1 eligible storefront", "research", "method", "generalisable", ["5953466116"])
c(3, "Warning 4; §9.H in-app rate menu; §3.7", "data-caveat", "Reviewers are mostly people for whom it worked: many reviews mark a milestone (REV_MILESTONE) and the app has an in-app 'rate this app' menu item; people who quietly gave up rarely return to write — the few who did are FAIL_ADMIT 37 (1.62%, mean 4.14), usually blaming themselves; the corpus 'measures what satisfied users value and what breaks for engaged users; it does not measure how many people quit silently'", "rate-this-app menu item; milestone reviews", "praise", "FAIL_ADMIT 37 (1.62%) 4.14", "research", "meaningful", "generalisable", ["7788169534","13609275319"])
c(4, "§0.1; §3.2 design of small commitments; §8.9", "product-rule", "The product works by subtraction — one small goal, one tap, thirty days: PR_SIMPLE 448 (19.56%, high-priority, mean 4.90, 2016 → 2026), PR_CONCEPT 262 (11.44%, 4.87), PR_ONE_GOAL 148 (6.46%, 4.87); ONE_GOAL_CONVERT 28 (1.22%) disliked the one-goal rule at first and came to agree with it: 'At first I thought it was hard to use, with too many restrictions, but I realised they are firmly based on the maker's philosophy of how to keep going'; 'At first I was saying let me add another goal!, but as I kept going I came to think this is how it should be'; the setup flow that pushes goals to five minutes or less is praised as a feature: 'I was really grateful that the app itself asked me, can you really do that in 5 minutes?'; 'just sit at the desk' — the small goal overflows (that reviewer now studies about two hours a day); the most-voted review (354 votes): 「信じてください。続きます。」 ('Believe me. It sticks.'); §8.9 keep the guided setup that shrinks goals, one goal, one tap", "one goal; ≤5-minute guided setup; 30-day ring", "5★-burst", "PR_SIMPLE 448 (19.56%) 4.90; PR_CONCEPT 262; PR_ONE_GOAL 148; ONE_GOAL_CONVERT 28; top review 354 votes", "product-rule", "high-priority", "generalisable", ["1558166349","13314939713","5953466116","5555608923","11834726322"])
c(5, "§0.1 outcomes; §3.2 outcomes table (verbatim)", "insight", "The outcome evidence is broad: U_OUTCOME 992 (43.32%, high-priority, mean 4.92) — streaks OUT_STREAK 617 (26.94%), chronic quitters who finally continued OUT_QUITTER 299 (13.06%; the 三日坊主 'three-day monk' identity appears in 343 reviews), behaviour that became automatic OUT_HABIT 194 (8.47%), concrete life results OUT_RESULT 157 (6.86%) (verbatim): " + table("### Outcomes and use contexts", 0) + " — streaks of 500 days, 1,000 days, a year or more; ordinary goals (sit-ups, one page, one minute of tidying, brushing teeth) with real change: 「無事に合格しました。」 ('I passed'); 'I'm a 54-year-old man, and I kept up 20 push-ups a day for a month'", "n/a", "praise", "U_OUTCOME 992 (43.32%) 4.92", "none", "high-priority", "generalisable", ["12259513979","8674571685","9679972581","1783528882"])
c(6, "§0.2; §3.2 encouragement; §8.9", "feature", "The encouragement layer keeps people coming back: PR_COMMENTS 428 (18.69%, high-priority, mean 4.93) — the daily one-line comment from the stick figure; PR_NOTIF 203 (8.86%, 4.84) the reminder that says 「やったれ！」 ('go for it!'); PR_HUMOR 106 (4.63%); PR_TIPS 102 (4.45%) — named more often than any feature except simplicity; many continue in order to see tomorrow's line: 'For someone starved of praise like me, this feature is truly the best'; 'The second notification arrived at a moment as if it had seen through my laziness'; §8.9 keep the encouragement line and humour as the default", "free encouragement voice", "praise", "PR_COMMENTS 428 (18.69%) 4.93; PR_NOTIF 203 (8.86%); PR_HUMOR 106; PR_TIPS 102", "build-free", "high-priority", "generalisable", ["5316192055","8737413152","11117049969","1549417557"])
c(7, "§0.2 tone; §3.6; §8.3", "must-have", "The same voice alienates a minority, loudly: tone and notification complaints NEG_COMMENT_TONE 7 ∪ NEG_NOTIF_ANNOY 9 = 14 (0.61%, emerging, mean 2.50, 2018-03-09 → 2025-06-20) — 3 before 2023, 11 from 2023, 9 in E4: 「これじゃ893と変わらないんですけど。」 ('This is no different from the yakuza', 18 votes); 'I definitely turned notifications off, yet they keep coming'; 'The jokey tone is way too cringey'; 'The cheerleading energy and jokiness give me goosebumps'; a flippant 'only when you reeeeally need to' warning; 'the badge makes me feel blamed all day and weighs on me' (5★); a long-term user asks for exactly the missing control — 'please let me switch the encouragement comments fully off'; the wellbeing audience makes it sensitive — 'a pushy tone that motivates one user can shame another'; §8.3: a quiet mode — one setting that switches the encouragement line, the 'are you sure' jokes and the badge to plain neutral text, keeping the voice as default", "no off switch for the voice", "1★-burst", "14 (0.61%) 2.50; 11 of 14 since 2023", "must-have", "emerging", "generalisable", ["7553106036","10598709745","10527702382","10317633924","10058846156","12796168055","11568521715"])
c(8, "§0.3; §3.5; §8.5", "feature", "The top feature request collides with the core design: REQ_MULTI 44 (1.92%, meaningful, mean 4.39) against PR_ONE_GOAL 148 praising the limit; growing — 4.7% of E5, the highest of any era; narrower than 'many habits': keep a habit already completed while starting the next — 'Once you complete 30 days and start a new habit, the old habit is no longer notified' (3★); 'Please let me record about three goals in parallel'; 'I wish if I can add just one more task, it would be so good 2 tasks a day'; reviewers volunteer the compromise — unlock a second goal only after a first 30-day cycle; §8.5: after a cycle offer 'keep tracking this quietly' alongside 'set the next goal' — one active goal with reminders and encouragement, graduated habits kept as a low-key streak; answers most of REQ_MULTI and REQ_PERIOD (13) without giving up the discipline 148 credit; test on 60- and 90-day continuation, not goals created", "one goal; finished habit fades", "mixed", "REQ_MULTI 44 (1.92%) 4.39; 4.7% of E5", "research", "meaningful", "generalisable", ["12651030354","14519088452","12157880557","1399663066","13760782567"])
c(9, "§0.4; §3.3 table (verbatim); §8.6", "must-have", "The rules are strict and real life breaks them: U_RULE_FRICTION 114 (4.98%, very strong, mean 4.06) — the two-day reset, fixed 30-day cycle and day boundary are the discipline; PR_RESET_TENSION 40 (1.75%) praise it; hurt when illness, a menstrual period or a school trip interrupts (REQ_PAUSE 10, NEG_RESET_RULE 14): 'sometimes you can't do it when you're unwell' (1★); 「生理が来ると、2日くらいお休みしたい人も中にはいるのです。」 ('When our period comes, some of us want about two days off'); strength-training users: rest days are part of training (REQ_FREQ 8); rule friction codes (verbatim): " + table("## 3.3 Friction with the rules", 0) + " — most still rate 4–5★ and ask for flexibility, not removal; §8.6: a limited honest rest day (e.g. two per cycle) plus an optional strict mode for those who want it — 'Both camps have existed since 2018, so a single rule will keep losing one of them'", "2-day reset; fixed 30 days; no pause", "mixed", "RULE_FRICTION 114 (4.98%) 4.06; PAUSE 10; RESET_RULE 14 (3.21)", "must-have", "very strong", "generalisable", ["1712808912","11522188751","1663994021","12884112714"])
c(10, "§0.4 reset split; §7.1 E1 → E2", "timeline", "The reset has split users since 2018: a March 2018 update removed the automatic reset — PR_RESET_REMOVED 6 (0.26%) welcomed it ('I'm personally glad this update abolished the reset') and REQ_RESET_BACK 13 (0.57%, mean 4.08) asked for it back as late as 2024 ('For some people motivation drops sharply without the reset'); the same update removed a 90-day option (NEG_90_REMOVED 3); reviews from 2020 again describe a two-day reset prompt with a 'don't reset' choice — whether the removal was later reversed in full could not be established", "reset removed Mar 2018", "mixed", "PR_RESET_REMOVED 6; REQ_RESET_BACK 13 (0.57%) 4.08; NEG_90_REMOVED 3", "research", "emerging", "generalisable", ["2304355241","2306392656"])
c(11, "§3.3 day boundary / longer cycles / no dates; §8.1", "must-have", "Day boundary, cycle length and visible dates: night workers and late studiers get caught between midnight and 3 a.m. ('if I record at 15:00 one day, I can't record at 10:00 the next'; NEG_DAYBOUNDARY 11, REQ_DAYBOUNDARY_SET 6) while a night-shift worker values choosing yesterday or today after midnight; people who finish 30 days want to keep counting ('I want to see how far I can extend the record beyond 30 days!'; REQ_PERIOD 13); no visible dates — 'because no dates are shown, from about day 3 I lost track of whether I'd recorded or not, got confused and uninstalled'; §8.1: show the date being recorded on the ring — most day-boundary confusion comes from not seeing which day a tap counts for", "no date on the ring; 3 a.m. boundary", "churn", "DAYBOUNDARY 11 (3.45); PREVDAY_FLOW 11; PERIOD 13; RULES_UNCLEAR 9", "must-have", "weak", "generalisable", ["6059617063","14505391902","12910203779","8693987085"])
c(12, "§0.5 table (verbatim); §3.4 table (verbatim); §8.1", "must-never-break", "Defects hit the one action that matters, recording today's success: U_BUG_ANY 104 (4.54%, very strong, mean 3.29), 24 of 50 1★ (48.00%) carry a defect code (verbatim): " + table("## 3.4 Reliability", 0) + " — recording blocked: tapping the ring shows the undo hint instead of recording, often from day 2 or 3 — 'A pop-up saying cancel with the top-right button appears; when I reluctantly delete it I'm back to day one' (BUG_INPUT 20, 2.75, reported 2017 → 2026); 'my five minutes of effort couldn't be recorded and went to waste'; 'There is a serious bug that, fairly often, wipes out the previous day's record'; wrong counts and phantom resets (counts stuck at 7 or 4, unrecorded flags on unscheduled weekdays); a user of several of the developer's apps: 'after a few months, all of them start producing an absurd run of bugs'; defect share falls 7.6% (E1) → 1.9% (E5) but recording defects persist a decade — 'For a product whose whole promise is an unbroken record, a lost day is the worst possible failure'; §8.1: eliminate the undo-hint loop, phantom resets and erased days; log every tap so a lost day can be restored", "recording taps lost", "1★-burst", "U_BUG_ANY 104 (4.54%) 3.29; 48% of 1★; BUG_INPUT 20; BUG_COUNT 12; BUG_RESET 7", "must-never-break", "very strong", "generalisable", ["5861217675","7136283910","13935906932","7566282416","1553783592","10172688755"])
c(13, "§3.4 notifications; §8.2", "must-never-break", "Notifications that do not obey: BUG_NOTIF 38 (1.66%, meaningful, mean 3.42) — missing, duplicated after a new cycle, continuing for a deleted goal, or arriving after being switched off; §8.2: honour notifications-off, remove notifications for deleted or completed goals, prevent duplicates on a new cycle; allow weekday / weekend reminder times and later edits (REQ_NOTIF_EDIT 10)", "notifications after off / deleted goal", "complaint", "BUG_NOTIF 38 (1.66%) 3.42; REQ_NOTIF_EDIT 10", "must-never-break", "meaningful", "generalisable", ["10598709745","1960898756"])
c(14, "§0.6; §2.3 table (verbatim); §5.1; §5.2", "monetization", "Money comes from patronage: the JP listing says the app is completely free and in-app purchase is 'only for people who want to support' it; MON_PAID_EXPLICIT 54 (2.36%, mean 4.76) bought the add-on; MON_WILL_PAY 90 (3.93%, 4.89) intend to ('after 30 days', 'when I have money'); MON_SUPPORT_DEV 39 (1.70%) frame paying as supporting the developer, not unlocking a function — 「自分も男気をみせて課金したりました」; 'I felt guilty about using it for free'; purchase triggers within 54 buyers: support for the developer 14 (25.93%; with any developer-bond code 19, 35.19%), a completed milestone as reward 22 (40.74%: '30日続けることができたので無駄機能買いました'; 'I'll buy the useless feature if I last a month'), more or different encouragement 14 (the free lines repeat every 30-day cycle), paying as a commitment device (MON_PAY_COMMIT 3: 'paying creates more sense of obligation'); free / paid (verbatim): " + table("## 2.3 Free / paid / trial", 0) + " — no trial described; a donation link unclear / intermittent (named in 23 reviews; in 2020 donations were not being accepted)", "free core; ¥960–980 message-pack add-on", "purchase-driver", "PAID 54 (2.36%) 4.76; WILL_PAY 90 (3.93%); SUPPORT_DEV 39 (1.70%)", "build-paid", "meaningful", "generalisable", ["1834959691","8317723251","6581562527","5246053794","3598813740","3667119040"])
c(15, "§5.3 table (verbatim); §5.4", "insight", "Segment rates among 54 purchasers (verbatim): " + table("## 5.3 Segment rates among purchasers", 0) + " — support-for-developer lift 15.22×; most purchasers satisfied (mean 4.76) and value variety and fun, especially the 中二病 voice ('I love that paying upgrades the comments a little. Paying was the right call!'); 4 of 54 unhappy name specific failures — content that felt no different before and after paying, quotations taken from famous people rather than original lines, the purchase still advertised after buying, and recording that broke after buying with no reply from support", "n/a", "purchase-driver", "54 purchasers @ 4.76; SUPPORT_DEV lift 15.22×", "none", "segment", "generalisable", ["5906598071","7262494547","6173882157"])
c(16, "§0.6 price; §5.5 table (verbatim); §8.7", "monetization", "Price is the barrier to patronage: MON_PRICE_HIGH 20 (0.87%, mean 4.65) and MON_NO_PAY 17 (0.74%, 5.00 — students, minors, tight budgets: 'my family says no in-app purchases'); the add-on cost ¥960–980 as a one-off (2017–2021) and since May 2022 reviewers describe it as monthly (MON_SUBSCRIPTION 7, first 2022-05-15): '¥980 is far too much. I'd happily pay around ¥300'; 'It's ¥980 a month as of April 2023, which feels a bit expensive'; 'Please add a way to donate ¥100 at a time, as often as I like'; 'it seems it used to be a one-off purchase and has changed to monthly, which is a shame'; 'a one-time purchase option would be nice too'; named thresholds ¥100–300, ¥500, repeatable ¥100 donations; non-monetary support offered — 'how about adding a watch an ad button to the menu?' and two bought the developer's book as support; barriers (verbatim): " + table("## 5.5 Upgrade barriers", 0) + " — §8.7: a small repeatable tip (¥100–300) or a one-time pack alongside the monthly plan, offered at the moment reviewers already choose to pay — completing a 30-day cycle; refresh the free message set between cycles or say plainly that a second cycle repeats it", "¥980 one-off → monthly", "blocked-conversion", "PRICE_HIGH 20 (0.87%); NO_PAY 17; SUBSCRIPTION 7", "research", "emerging", "generalisable", ["5601520030","9872904162","13157065902","10068902732","8886936066","5441799315","12677032119"])
c(17, "§5.6; §8.4", "dont", "No purchase screen that can be tapped by accident: only 2 ask for money back — 'I couldn't work out how to turn the useless feature off' (then charged ¥960) and a paid feature not delivered with no reply; unwanted purchase prompts produce the harshest words: 「しかも誤課金しやすい画面。970円も誤課金した。」 ('the screen makes mis-purchases easy. I mistakenly paid ¥970'); 「いきなりの金銭要求。」 ('a sudden demand for money'), calling the app 「詐欺に近い」 (close to fraud); MON_ACCIDENTAL 2, NEG_UPSELL_NAG 5 (mean 1.40), BUG_IAP 4 purchase stuck / not restored; post-purchase and purchase-prompt complaints 11 (mean 2.18); §8.4: require explicit confirmation on the add-on, stop showing it to people who already bought, add a clear way to turn a pack off", "easy mis-purchase; prompt after buying", "1★-burst", "ACCIDENTAL 2 @ 1.00; UPSELL_NAG 5 @ 1.40; BUG_IAP 4", "dont", "weak", "generalisable", ["3554026149","6572812402","3209298921","12643702172","7262494547"])
c(18, "§0.7; §3.1 U_DEV_BOND", "tactic", "The developer's voice is a differentiator that is fading from the reviews: U_DEV_BOND 364 (15.90%, high-priority, mean 4.92) — praise for the developer's attitude, essays and release notes (PR_DEV 311, 13.58%; PR_RELNOTES 28, 1.22% — release notes read as content) and installs of the developer's other apps (XSELL_OTHER_APP 78, 3.41%; from 2018-06 the sister app 「集中」 'Focus'); 'It's also the first app I've seen that replies to every review one by one'; outcome: this goodwill is what the purchase model runs on (developer-bond among 35.19% of purchasers); PR_DEV falls 18.5% of E2 → 5.2% of E5 (sensitivity: dev bond 15.9% all vs 8.9% in E4 + E5); unanswered support mail SUP_NONE 5 (0.22%) about purchases, a notification defect or a feature request ('I sent an email. But there was no reply'); §8.9 keep the developer's voice — 'It is what purchasers say they are paying for'", "replies to every review; essay release notes", "praise", "U_DEV_BOND 364 (15.90%) 4.92; PR_DEV 18.5% → 5.2%; XSELL 78", "do", "high-priority", "generalisable", ["1767172314","6986884299","1544232487","2246132063"])
c(19, "§3.2 free, no ads, no data", "product-rule", "Free, no ads, no data: PR_FREE 149 (6.51%, high-priority, mean 4.87), rising from 1.4% of E1 to 11.2% of E3 as reviewers contrast ad-supported and subscription-first apps they tried (CMP_OTHER_APPS 60); PR_PRIVACY 4 add that it collects no personal data; 「このアプリ全然お金の匂いがしないんです。」 ('This app doesn't smell of money at all'); §8.9 keep no ads, no data collection and no forced payment — 'named as reasons to trust and to pay'", "free, no ads, no personal data", "praise", "PR_FREE 149 (6.51%) 4.87; 1.4% → 11.2%", "product-rule", "high-priority", "generalisable", ["5893755217","1757827408","13157065902"])
c(20, "§3.2 mental health; §3.6", "audience", "Mental health and self-care context: USE_WELLBEING 25 (1.09%, meaningful, mean 4.92) — depression, ADHD, anxiety, autonomic disorders and binge eating named with recovery stories: 'My depression has eased and I've been able to return to work'; 'When I managed to brush my teeth every morning for 30 days, I felt a little closer to normal and was really happy'; 'It's day 15 since the stress-driven late-night binge eating I'd suffered for about eight years stopped' — 'This is a sensitive audience… a pushy tone that motivates one user can shame another'", "n/a", "praise", "USE_WELLBEING 25 (1.09%) 4.92", "do", "meaningful", "generalisable", ["8115938123","12055574930","14089761799"])
